"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, useScroll, useSpring } from "motion/react";
import DotSphere from "./DotSphere";
import { site } from "@/data/site";

const links = [
  { href: "/", label: "Work" },
  { href: "/bio", label: "Bio" },
  { href: "/contact", label: "Contact" },
];

export default function Nav() {
  const pathname = usePathname();
  const { scrollYProgress } = useScroll();
  const progress = useSpring(scrollYProgress, { stiffness: 200, damping: 30 });

  const isActive = (href: string) =>
    href === "/" ? pathname === "/" || pathname.startsWith("/projects") : pathname.startsWith(href);

  return (
    <header className="fixed inset-x-0 top-0 z-50 bg-black/75 backdrop-blur-md">
      <nav className="mx-auto flex h-20 max-w-[1280px] items-center justify-between px-5 sm:px-10">
        <Link href="/" className="flex items-center gap-3 sm:gap-5">
          <DotSphere size={44} />
          <span className="font-dot text-xl sm:text-2xl">{site.brand}</span>
        </Link>
        <ul className="flex gap-6 text-xs sm:gap-12">
          {links.map((l) => (
            <li key={l.href}>
              <Link
                href={l.href}
                className={
                  isActive(l.href)
                    ? "font-bold underline underline-offset-4"
                    : "transition-colors hover:text-accent"
                }
              >
                {l.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
      <motion.div
        style={{ scaleX: progress }}
        className="absolute inset-x-0 bottom-0 h-px origin-left bg-accent"
      />
    </header>
  );
}
