"use client";

import { useEffect, useRef } from "react";

/**
 * 粒子球 Logo：一圈点组成的球体缓慢旋转，鼠标悬停时加速。
 * 用 canvas 画，不依赖图片。
 */
export default function DotSphere({ size = 44 }: { size?: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const speed = useRef(1);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    ctx.scale(dpr, dpr);

    // 斐波那契球面均匀取点
    const N = 260;
    const pts = Array.from({ length: N }, (_, i) => {
      const y = 1 - (i / (N - 1)) * 2;
      const r = Math.sqrt(1 - y * y);
      const t = i * Math.PI * (3 - Math.sqrt(5));
      return [Math.cos(t) * r, y, Math.sin(t) * r];
    });

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let angle = 0;
    let raf = 0;
    const R = size * 0.42;
    const c = size / 2;
    const tilt = 0.45;

    const draw = () => {
      ctx.clearRect(0, 0, size, size);
      const cosA = Math.cos(angle), sinA = Math.sin(angle);
      const cosT = Math.cos(tilt), sinT = Math.sin(tilt);
      for (const [x, y, z] of pts) {
        // 绕 Y 轴旋转，再绕 X 轴倾斜
        const x1 = x * cosA - z * sinA;
        const z1 = x * sinA + z * cosA;
        const y2 = y * cosT - z1 * sinT;
        const z2 = y * sinT + z1 * cosT;
        const depth = (z2 + 1) / 2; // 0 = 后面, 1 = 前面
        ctx.globalAlpha = 0.15 + depth * 0.85;
        ctx.fillStyle = "#fff";
        ctx.beginPath();
        ctx.arc(c + x1 * R, c + y2 * R, 0.35 + depth * 0.75, 0, Math.PI * 2);
        ctx.fill();
      }
      angle += 0.006 * speed.current;
      speed.current += (1 - speed.current) * 0.03;
      if (!reduce) raf = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf);
  }, [size]);

  return (
    <canvas
      ref={ref}
      aria-hidden
      style={{ width: size, height: size }}
      onMouseEnter={() => (speed.current = 8)}
    />
  );
}
